public class Solution {
    public int[] FindPeakGrid(int[][] mat) {

        // Raj Thomas 28th Jun 2026 12:35AM IST 
        int len = mat.Length;
        for(int row = 0; row < len; row++) {
            int colLen = mat[row].Length;

            for(int col = 0; col < colLen; col++) {

                if(IsPeak(mat, row, col, len, colLen)) {
                    return new int[2] { row, col };
                }
            }
        }

        return new int[2] { -1, -1 };
    }

    private bool IsPeak(int[][] mat, int row, int col, int rowLen, int colLen) {

        int r = row, c = col;
        int ele = mat[row][col];

        int left = row == 0 ? -1 : mat[row - 1][col];
        int right = row == rowLen - 1 ? -1 : mat[row + 1][col];
        int top = col == 0 ? -1 : mat[row][col - 1];
        int bottom = col == colLen - 1 ? -1 : mat[row][col + 1];

        if(ele > left && ele > right && ele > top && ele > bottom) return true;

        return false;

    }
}
